import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry max_reduce_3d(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 D0,
    .param .u32 D1,
    .param .u32 D2,
    .param .u64 S0,
    .param .u64 S1,
    .param .u64 S2,
    .param .u32 reduce_dim
)
{
    .reg .pred p0, p1, p2, pGuard, pLane0, pWarp0, pLt;
    .reg .b32 rTid, rBid, rNtid;
    .reg .b32 rD0, rD1, rD2, rRed;
    .reg .b32 rA, rB, rNout, rQ, rR, rRD, rK;
    .reg .b32 rLane, rWarp;
    .reg .b32 rVal, rTmp, rMask;
    .reg .f32 fMax, fTmp;
    .reg .b64 inPtr, outPtr;
    .reg .b64 S0_64, S1_64, S2_64, Sred, base, addr, off, byte_off;
    .reg .b64 rdI0, rdI1, rdI2, rdK64, t0, t1, t2, smemBase, sPtr, sOff64;
    .reg .b32 rI0, rI1, rI2, sOff;

    .shared .align 4 .b8 smem[128];

    mov.u64 smemBase, smem;
    ld.param.u64 inPtr, [in_ptr];
    ld.param.u64 outPtr, [out_ptr];
    ld.param.u32 rD0, [D0];
    ld.param.u32 rD1, [D1];
    ld.param.u32 rD2, [D2];
    ld.param.u64 S0_64, [S0];
    ld.param.u64 S1_64, [S1];
    ld.param.u64 S2_64, [S2];
    ld.param.u32 rRed, [reduce_dim];

    cvta.to.global.u64 inPtr, inPtr;
    cvta.to.global.u64 outPtr, outPtr;
    mov.u32 rTid, %tid.x;
    mov.u32 rBid, %ctaid.x;
    mov.u32 rNtid, %ntid.x;

    setp.eq.u32 p0, rRed, 0;
    setp.eq.u32 p1, rRed, 1;
    setp.eq.u32 p2, rRed, 2;

    selp.u32 rB, rD1, rD2, p2;        // B = (red==2 ? D1 : D2)
    selp.u32 rA, rD1, rD0, p0;        // A = (red==0 ? D1 : D0)
    mul.lo.u32 rNout, rA, rB;

    setp.ge.u32 pGuard, rBid, rNout;
    @pGuard bra EXIT;

    div.u32 rQ, rBid, rB;
    rem.u32 rR, rBid, rB;

    mov.u32 rI0, 0;
    mov.u32 rI1, 0;
    mov.u32 rI2, 0;

    selp.u32 rI1, rQ, rI1, p0;
    selp.u32 rI2, rR, rI2, p0;

    selp.u32 rI0, rQ, rI0, p1;
    selp.u32 rI2, rR, rI2, p1;

    selp.u32 rI0, rQ, rI0, p2;
    selp.u32 rI1, rR, rI1, p2;

    mov.u32 rRD, rD0;
    selp.u32 rRD, rD1, rRD, p1;
    selp.u32 rRD, rD2, rRD, p2;

    mov.b64 Sred, S0_64;
    selp.u64 Sred, S1_64, Sred, p1;
    selp.u64 Sred, S2_64, Sred, p2;

    cvt.u64.u32 rdI0, rI0;
    cvt.u64.u32 rdI1, rI1;
    cvt.u64.u32 rdI2, rI2;

    mul.lo.u64 t0, rdI0, S0_64;
    mul.lo.u64 t1, rdI1, S1_64;
    mul.lo.u64 t2, rdI2, S2_64;

    add.u64 base, t0, t1;
    add.u64 base, base, t2;

    mov.b32 rVal, 0xff800000;  // -inf
    mov.b32 fMax, rVal;

    mov.u32 rK, rTid;
LOOP:
    setp.ge.u32 pGuard, rK, rRD;
    @pGuard bra REDUCE;

    cvt.u64.u32 rdK64, rK;
    mul.lo.u64 off, rdK64, Sred;
    add.u64 off, base, off;
    shl.b64 byte_off, off, 2;

    add.u64 addr, inPtr, byte_off;
    ld.global.f32 fTmp, [addr];
    max.f32 fMax, fMax, fTmp;

    add.u32 rK, rK, rNtid;
    bra LOOP;

REDUCE:
    // removed invalid %activemask; using activemask.b32 rMask
    activemask.b32 rMask;
    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 16, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 8, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 4, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 2, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 1, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.u32 rLane, %laneid;
    shr.u32 rWarp, rTid, 5;

    setp.eq.u32 pLane0, rLane, 0;
    @pLane0 mov.u32 sOff, rWarp;
    @pLane0 shl.b32 sOff, sOff, 2;
     @pLane0 cvt.u64.u32 sOff64, sOff;
    @pLane0 add.u64 sPtr, smemBase, sOff64;
    @pLane0 st.shared.f32 [sPtr], fMax;
    bar.sync 0;

    setp.eq.u32 pWarp0, rWarp, 0;
    @!pWarp0 bra WRITE;

    add.u32 rQ, rNtid, 31;
    shr.u32 rQ, rQ, 5; // nwarps

    setp.ge.u32 pLt, rLane, rQ;
    @pLt mov.b32 rVal, 0xff800000;
    @pLt mov.b32 fMax, rVal;
    @!pLt mov.u32 sOff, rLane;
    @!pLt shl.b32 sOff, sOff, 2;
     @!pLt cvt.u64.u32 sOff64, sOff;
    @!pLt add.u64 sPtr, smemBase, sOff64;
    @!pLt ld.shared.f32 fMax, [sPtr];

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 16, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 8, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 4, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 2, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

    mov.b32 rVal, fMax;
    shfl.sync.down.b32 rTmp, rVal, 1, 0x1f, rMask;
    mov.b32 fTmp, rTmp;
    max.f32 fMax, fMax, fTmp;

WRITE:
    setp.eq.u32 pLane0, rTid, 0;
    @!pLane0 bra EXIT;

    cvt.u64.u32 byte_off, rBid;
    shl.b64 byte_off, byte_off, 2;
    add.u64 addr, outPtr, byte_off;
    st.global.f32 [addr], fMax;

EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("max_reduce_3d")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 input is supported"
        assert x.dim() == 3, "Input must be a 3D tensor"

        assert x.storage_offset() == 0, "Input tensor must have zero storage offset"
        D0, D1, D2 = x.size(0), x.size(1), x.size(2)
        S0, S1, S2 = x.stride(0), x.stride(1), x.stride(2)

        dim = self.dim
        if dim < 0:
            dim += 3
        assert dim in (0, 1, 2), "Reduction dim must be 0, 1, or 2"

        if dim == 0:
            out_shape = (D1, D2)
        elif dim == 1:
            out_shape = (D0, D2)
        else:
            out_shape = (D0, D1)

        out = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        module = _get_ptx_module()

        if dim == 0:
            nout = D1 * D2
        elif dim == 1:
            nout = D0 * D2
        else:
            nout = D0 * D1

        block_x = 256
        grid_x = nout

        module.launch(
            "max_reduce_3d",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                out,
                u32(D0), u32(D1), u32(D2),
                u64(int(S0)), u64(int(S1)), u64(int(S2)),
                u32(dim),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

